using System;using UnityEngine;using UnityEngine.UI;
namespace Ssalddel.Unity.Experiments.CityFarmWorldIntegration{[RequireComponent(typeof(Button))]public sealed class PotatoHubReceivingActionButton:MonoBehaviour{[SerializeField]private PotatoHubReceivingLifecyclePresenter presenter=null!;[SerializeField]private string actionCode=string.Empty;public void Configure(PotatoHubReceivingLifecyclePresenter p,string c){presenter=p;actionCode=c;}private void Awake()=>GetComponent<Button>().onClick.AddListener(Execute);public void Execute(){if(presenter==null||string.IsNullOrWhiteSpace(actionCode))throw new InvalidOperationException("PotatoHubReceivingButtonInvalid");presenter.ExecuteAction(actionCode);}}}
